css:
/* COLUMNS ARE ATOMS. Every row shares one column track list, so a
   substituent in the row above lands exactly over its own carbon and the
   `|` between them meets it. This is the whole reason the structure is a
   grid: laid out as text, `CH3` went wherever the line breaker put it. */
.cst { display:inline-grid; grid-auto-rows:auto; justify-items:center;
       align-items:center; margin:10px 0; white-space:nowrap; }
.cst>.cst-r { display:grid; grid-template-columns:subgrid;
              grid-column:1 / -1; }

/* The chain itself carries the page's notation size; bonds are given a
   little room either side so `CH₃ — CH` reads as a bond and not a dash in
   a word. */
.cst>.cst-c>span { line-height:1.2; }
.cst>.cst-c>span:nth-child(even) { padding:0 3px; }

/* A vertical bond. A single glyph in its own row, tight against the atom
   above and below it, so the bond looks continuous rather than like a
   stray pipe character. */
.cst>.cst-bond>span { line-height:0.72; font-size:1.05em; }

/* A substituent — same size as the chain, because it is part of the
   molecule and not an annotation on it. */
.cst>.cst-sub>span { line-height:1.15; }

/* CARBON NUMBERS. Small, quiet, and in their own row so they line up
   with each other as well as with their atoms — a locant that has drifted
   is worse than no locant, because the question turns on which carbon it
   is. */
.cst>.cst-n>span { font-size:.66em; line-height:1.3; opacity:.72;
       font-family:inherit; font-style:normal; }

/* The IUPAC name, under the structure it names — which is where the
   question asks for it and where a textbook prints it. Centred on the
   molecule, not on the column, so it reads as a label on the drawing
   rather than as the next sentence. */
.cst-name { grid-column:1 / -1; text-align:center; margin-top:5px;
     font-style:normal; font-family:inherit; opacity:.9; }
